INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 7, 1, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'WitchCaveComplete');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 12, 1, NULL, 'WitchCaveComplete');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'I buried Wystan''s band beside his empty grave, and I sleep through the night now.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Mind yourself in the dark places. And if you meet my nephew Geowulf on the road, tell him his aunt says to come home for supper.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 13, 1, NULL, 'WitchCaveComplete');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 21, 0, 1, 'WitchCaveStarted');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 12, 1, NULL, 'WitchCaveStarted');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The cave is in the glade of grey stones north-west of town, at 31.0N 25.0E.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Bring me Wystan''s band, if there is anything left of him to bring.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 13, 1, NULL, 'WitchCaveStarted');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'You have the look of someone who does not mind the dark. Will you hear an old woman out?');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Thirty years ago my husband Wystan followed a light into the hills north-west of here. There is a cave under the grey stones, and every autumn a light burns in its mouth. Folk say it is Empyrean fire over buried gold. Wystan believed them.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'He went in with a lantern, a spade and a promise to be home for supper. He never came home. The light still burns.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 10, 1, 1, 'My nephew Geowulf says I should let it lie. But I would know what became of him. He wore a plain gold band, the twin of mine. If you find it, bring it to me.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 4, 10, 1, 1, 'The cave is at 31.0N 25.0E. Keep to your lantern, and do not listen to anything that speaks to you down there.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 5, 22, 0, 1, 'WitchCaveStarted');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 6, 1, 901555, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'WitchCaveComplete@Band');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 12, 1, NULL, 'WitchCaveComplete@Band');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Another band? Then she took more than my Wystan. Keep it, and find its family if you can.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, weenie_Class_Id, stack_Size) VALUES (@e, 1, 3, 0, 1, 901555, 1);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901550, 13, 1, NULL, 'WitchCaveComplete@Band');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'That is his. I would know it anywhere. We had our names cut inside, and there they are.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'So it was her. My mother used to frighten us with tales of the Hollow Crone who kept a fire in the hill, and we laughed at her.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'I have worn the twin of this band for thirty years, waiting. I do not need to wait any more. Take mine. It kept me safe; let it keep you.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 10, 1, 1, 'Geowulf talks of walking the northern coast. The old tales say the witch was only a servant, and that her mistress sleeps somewhere across the water. I pray he keeps out of such places.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 4, 22, 0, 1, 'WitchCaveComplete');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 5, 22, 0, 1, 'WitchCaveStarted');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, percent, min_64, max_64) VALUES (@e, 6, 49, 0, 1, 0.2, 0, 5000000);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, weenie_Class_Id, stack_Size) VALUES (@e, 7, 3, 0, 1, 901556, 1);
